-- CA-001F records verification coordination and canonical references only.
create table public.production_verification_plans(id uuid primary key default gen_random_uuid(),code text not null,version integer not null check(version>0),status text not null check(status in('draft','active','retired')),definition jsonb not null,published_at timestamptz,retired_at timestamptz,unique(code,version));
create table public.production_verification_scenarios(id uuid primary key default gen_random_uuid(),code text not null,version integer not null check(version>0),status text not null check(status in('draft','active','retired')),definition jsonb not null,unique(code,version));
create table public.production_verification_evidence_definitions(id uuid primary key default gen_random_uuid(),code text not null,version integer not null check(version>0),status text not null check(status in('draft','active','retired')),definition jsonb not null,unique(code,version));
create table public.production_release_candidates(id uuid primary key default gen_random_uuid(),environment_code text not null check(environment_code='production'),repository_code text not null,commit_sha text not null,deployment_id text not null,deployment_url text not null,production_alias text not null,build_id text,deployed_at timestamptz not null,database_migration_set_hash text not null,latest_migration_code text not null,registry_versions jsonb not null,verification_plan_version integer not null,feature_configuration_fingerprint text not null,created_at timestamptz not null default now(),unique(environment_code,deployment_id,commit_sha));
create table public.production_verification_runs(id uuid primary key default gen_random_uuid(),release_candidate_id uuid not null references public.production_release_candidates(id),plan_code text not null,plan_version integer not null,environment_code text not null check(environment_code='production'),status text not null check(status in('draft','ready','running','paused','blocked','awaiting_review','passed','failed','cancelled')),initiated_by uuid not null references public.profiles(id),reviewed_by uuid references public.profiles(id),started_at timestamptz,completed_at timestamptz,correlation_id text not null,revision integer not null default 1,gate_decision jsonb,created_at timestamptz not null default now());
create unique index production_verification_active_run_uidx on public.production_verification_runs(release_candidate_id,plan_code,plan_version)where status in('draft','ready','running','paused','blocked','awaiting_review');
create table public.production_verification_instances(id uuid primary key default gen_random_uuid(),verification_run_id uuid not null references public.production_verification_runs(id),scenario_code text not null,scenario_version integer not null,product_family text,controlled_identity_set_id uuid,logical_resource_set_id uuid,status text not null check(status in('pending','ready','running','waiting','passed','failed','blocked','skipped','cancelled')),latest_attempt_number integer not null default 0,expected_outcome_code text not null,actual_outcome_code text,blocker_code text,started_at timestamptz,completed_at timestamptz,revision integer not null default 1,unique(verification_run_id,scenario_code,scenario_version));
create table public.production_verification_attempts(id uuid primary key default gen_random_uuid(),scenario_instance_id uuid not null references public.production_verification_instances(id),attempt_number integer not null check(attempt_number>0),executor_code text not null,initiated_by uuid not null references public.profiles(id),correlation_id text not null,causation_id text,idempotency_key_hash text not null,status text not null check(status in('requested','running','succeeded','failed','timed_out','cancelled')),stable_result_code text,started_at timestamptz not null,completed_at timestamptz,unique(scenario_instance_id,attempt_number),unique(idempotency_key_hash));
create unique index production_verification_active_attempt_uidx on public.production_verification_attempts(scenario_instance_id)where status in('requested','running');
create table public.controlled_verification_identities(id uuid primary key default gen_random_uuid(),environment_code text not null check(environment_code='production'),identity_type_code text not null,opaque_auth_subject_reference text not null,tenant_id uuid,customer_account_id uuid,status text not null check(status in('active','reserved','retired')),allowed_scenario_codes text[] not null,expires_at timestamptz,created_under_policy_code text not null,unique(environment_code,opaque_auth_subject_reference));
create table public.production_verification_resources(id uuid primary key default gen_random_uuid(),verification_run_id uuid not null references public.production_verification_runs(id),scenario_instance_id uuid references public.production_verification_instances(id),owning_domain_code text not null,resource_type_code text not null,opaque_resource_id text not null,creation_classification text not null check(creation_classification in('created','reused','preexisting_fixture')),cleanup_classification text not null check(cleanup_classification in('required','retain','owning_domain_retention','not_applicable')),cleanup_status text not null check(cleanup_status in('pending','completed','failed','retained')),created_at timestamptz not null default now(),cleaned_at timestamptz,unique(verification_run_id,owning_domain_code,resource_type_code,opaque_resource_id));
create table public.production_verification_evidence(id uuid primary key default gen_random_uuid(),verification_run_id uuid not null references public.production_verification_runs(id),scenario_instance_id uuid not null references public.production_verification_instances(id),evidence_code text not null,evidence_version integer not null,source_domain_code text not null,source_resource_type text not null,opaque_source_reference text not null,classification text not null check(classification in('valid','invalid','missing','expired','superseded')),observed_outcome_code text not null,captured_at timestamptz not null,valid_through timestamptz,captured_by text not null check(captured_by in('system','verifier','reviewer')),correlation_id text not null);
create table public.production_verification_manual_observations(id uuid primary key default gen_random_uuid(),scenario_instance_id uuid not null references public.production_verification_instances(id),observation_code text not null,observation_version integer not null,result text not null check(result in('pass','fail','blocked')),reason_code text,observed_by uuid not null references public.profiles(id),observed_at timestamptz not null,safe_comment text check(length(safe_comment)<=1000));
create table public.production_verification_gate_evaluations(id uuid primary key default gen_random_uuid(),verification_run_id uuid not null references public.production_verification_runs(id),status text not null check(status in('pass','fail','blocked')),policy_code text not null,policy_version integer not null,counts jsonb not null,blocker_codes text[] not null,approved_limitation_codes text[] not null,evaluated_at timestamptz not null,reviewed_by uuid references public.profiles(id));
create table public.production_verification_audit_events(id uuid primary key default gen_random_uuid(),verification_run_id uuid not null references public.production_verification_runs(id),scenario_instance_id uuid references public.production_verification_instances(id),actor_id uuid references public.profiles(id),event_type text not null,outcome_code text not null,correlation_id text not null,occurred_at timestamptz not null default now());
create index production_verification_run_status_idx on public.production_verification_runs(status,created_at);create index production_verification_instance_queue_idx on public.production_verification_instances(verification_run_id,status);create index production_verification_cleanup_idx on public.production_verification_resources(verification_run_id,cleanup_status);
alter table public.production_verification_plans enable row level security;alter table public.production_verification_scenarios enable row level security;alter table public.production_verification_evidence_definitions enable row level security;alter table public.production_release_candidates enable row level security;alter table public.production_verification_runs enable row level security;alter table public.production_verification_instances enable row level security;alter table public.production_verification_attempts enable row level security;alter table public.controlled_verification_identities enable row level security;alter table public.production_verification_resources enable row level security;alter table public.production_verification_evidence enable row level security;alter table public.production_verification_manual_observations enable row level security;alter table public.production_verification_gate_evaluations enable row level security;alter table public.production_verification_audit_events enable row level security;
create policy "admins read verification plans" on public.production_verification_plans for select to authenticated using(public.is_admin());create policy "admins read verification scenarios" on public.production_verification_scenarios for select to authenticated using(public.is_admin());create policy "admins read verification evidence definitions" on public.production_verification_evidence_definitions for select to authenticated using(public.is_admin());create policy "admins read release candidates" on public.production_release_candidates for select to authenticated using(public.is_admin());create policy "admins read verification runs" on public.production_verification_runs for select to authenticated using(public.is_admin());create policy "admins read verification instances" on public.production_verification_instances for select to authenticated using(public.is_admin());create policy "admins read verification attempts" on public.production_verification_attempts for select to authenticated using(public.is_admin());create policy "admins read controlled identities" on public.controlled_verification_identities for select to authenticated using(public.is_admin());create policy "admins read verification resources" on public.production_verification_resources for select to authenticated using(public.is_admin());create policy "admins read verification evidence" on public.production_verification_evidence for select to authenticated using(public.is_admin());create policy "admins read verification observations" on public.production_verification_manual_observations for select to authenticated using(public.is_admin());create policy "admins read verification gates" on public.production_verification_gate_evaluations for select to authenticated using(public.is_admin());create policy "admins read verification audit" on public.production_verification_audit_events for select to authenticated using(public.is_admin());
revoke all on public.production_verification_plans,public.production_verification_scenarios,public.production_verification_evidence_definitions,public.production_release_candidates,public.production_verification_runs,public.production_verification_instances,public.production_verification_attempts,public.controlled_verification_identities,public.production_verification_resources,public.production_verification_evidence,public.production_verification_manual_observations,public.production_verification_gate_evaluations,public.production_verification_audit_events from anon,authenticated;
grant select on public.production_verification_plans,public.production_verification_scenarios,public.production_verification_evidence_definitions,public.production_release_candidates,public.production_verification_runs,public.production_verification_instances,public.production_verification_attempts,public.controlled_verification_identities,public.production_verification_resources,public.production_verification_evidence,public.production_verification_manual_observations,public.production_verification_gate_evaluations,public.production_verification_audit_events to authenticated;
